CREATE OR REPLACE FUNCTION public.guard_profile_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  caller uuid := auth.uid();
begin
  new.updated_at := now();

  if caller is null then
    return new;
  end if;

  if new.id is distinct from old.id then
    raise exception 'Hindi puwedeng palitan ang id.';
  end if;

  if new.role is distinct from old.role and not public.is_admin() then
    raise exception 'Admin lang ang puwedeng magpalit ng role.';
  end if;

  if old.role = 'admin' and old.id <> caller and not public.is_admin() then
    raise exception 'Hindi puwedeng baguhin ang profile ng admin.';
  end if;

  if not public.is_staff() then
    if new.status is distinct from old.status
       or new.email is distinct from old.email
       or new.username is distinct from old.username
       or new.category is distinct from old.category
       or new.ministry_group is distinct from old.ministry_group
       or new.baptism_status is distinct from old.baptism_status
       or new.baptism_date is distinct from old.baptism_date
       or new.member_since is distinct from old.member_since then
      raise exception 'Staff lang ang puwedeng magbago ng status, username, category, ministry, binyag, at petsa ng pagsapi.';
    end if;
  end if;

  return new;
end $function$

CREATE OR REPLACE FUNCTION public.send_weekly_local_finance_report()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_admin_ids uuid[];
  v_window_start timestamptz;
  v_window_end timestamptz;
  v_group record;
  v_letter_id uuid;
  v_lines text;
  v_body text;
  v_locality_label text;
  v_treasurer_name text;
  v_new_count int;
  v_edit_count int;
  v_range_label text;
begin
  v_window_end := now();
  v_window_start := v_window_end - interval '7 days';
  v_range_label := to_char(v_window_start at time zone 'Asia/Manila', 'Mon DD') || ' - ' ||
                    to_char(v_window_end at time zone 'Asia/Manila', 'Mon DD, YYYY');

  select array_agg(id) into v_admin_ids
  from public.profiles
  where role in ('admin', 'secretary', 'treasurer');

  if v_admin_ids is null then
    return;
  end if;

  for v_group in
    select distinct fr.locality, fr.updated_by
    from public.financial_records fr
    where fr.updated_at >= v_window_start
      and fr.updated_at <= v_window_end
      and fr.updated_by is not null
  loop
    v_locality_label := case v_group.locality
      when 'medina' then 'Medina'
      when 'batangas' then 'Sta. Teresita'
      when 'fort_mcmurray' then 'Fort Mcmurray'
      when 'other' then 'Online'
      else v_group.locality
    end;

    select full_name into v_treasurer_name
    from public.profiles where id = v_group.updated_by;
    v_treasurer_name := coalesce(v_treasurer_name, 'Hindi kilalang user');

    select
      count(*) filter (where fr.created_at >= v_window_start),
      count(*) filter (where fr.created_at < v_window_start)
    into v_new_count, v_edit_count
    from public.financial_records fr
    where fr.updated_at >= v_window_start
      and fr.updated_at <= v_window_end
      and fr.locality = v_group.locality
      and fr.updated_by = v_group.updated_by;

    select string_agg(
      '- ' || to_char(fr.record_month, 'FMMonth YYYY') || ' - ' ||
      (case fr.category
        when 'abuluyan' then 'Abuluyan'
        when 'ambagan' then 'Ambagan'
        when 'tulong_sa_aral' then 'Tulong sa Aral'
        when 'pasalamat' then 'Pasalamat'
        else fr.category
      end) || ': ' || to_char(fr.amount, 'FM999,999,990.00') ||
      (case when fr.created_at >= v_window_start then ' (bagong encode)' else ' (na-edit)' end),
      E'\n'
      order by fr.record_month, fr.category
    )
    into v_lines
    from public.financial_records fr
    where fr.updated_at >= v_window_start
      and fr.updated_at <= v_window_end
      and fr.locality = v_group.locality
      and fr.updated_by = v_group.updated_by;

    v_body := v_treasurer_name || ' - ' || v_locality_label || ' (' || v_range_label || ')' || E'\n' ||
              'Bagong na-encode: ' || v_new_count || ' - Na-edit: ' || v_edit_count || E'\n\n' || v_lines;

    insert into public.letters (subject, created_by)
    values (
      'Lingguhang Ulat ng Finance - ' || v_locality_label || ' - ' || v_range_label,
      v_group.updated_by
    )
    returning id into v_letter_id;

    insert into public.letter_recipients (letter_id, profile_id)
    select v_letter_id, admin_id
    from unnest(v_admin_ids) as admin_id;

    insert into public.letter_messages (letter_id, author_id, body)
    values (v_letter_id, v_group.updated_by, v_body);
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.touch_financial_record_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$
